<?php declare(strict_types=1);use Cms\Core\Theme\TemplateContext;/** @var TemplateContext $context */require_once dirname(__DIR__).'/_theme.php';$seo=$context->seo();$items=dj_items($context);$rawPagination=$context->get('pagination',[]);$rawPagination=is_array($rawPagination)?$rawPagination:[];$currentPage=max(1,(int)($rawPagination['page']??1));$perPage=max(1,(int)($rawPagination['per_page']??10));$totalItems=max(count($items),(int)($rawPagination['total']??count($items)));$totalPages=max(1,(int)ceil($totalItems/$perPage));$basePath=(string)$context->get('base_path','/articles');$basePath=trim($basePath)!==''?$basePath:'/articles';$pager=$context->pagination($currentPage,$totalPages,$basePath,[],$perPage,$totalItems);?><!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?= $context->e((string)($seo['title']??'典籍')) ?></title><link rel="stylesheet" href="<?= $context->e($context->asset('css/style.css')) ?>"></head><body class="dj-theme dj-paper-page"><?php require dirname(__DIR__).'/partials/header.php';?><main class="dj-list"><div class="dj-page-heading"><span>DAOJIA</span><h1><?= $context->e((string)$context->get('page_title','典籍与心悟')) ?></h1></div><div class="dj-grid"><?php foreach($items as $item):$u=dj_content_url($item);?><article class="dj-card"><div><time><?= $context->e(dj_date($item['published_at']??$item['created_at']??'')) ?></time><h2><a href="<?= $context->e($u) ?>"><?= $context->e((string)($item['title']??'')) ?></a></h2><p><?= $context->e(dj_excerpt($item)) ?></p><a class="dj-read" href="<?= $context->e($u) ?>">阅读全文 →</a></div></article><?php endforeach;?></div><?php if(($pager['total_items']??0)>$perPage):?><nav class="dj-pagination dj-server-pagination" aria-label="文章分页"><?php if(!empty($pager['has_prev'])&&!empty($pager['prev_url'])):?><a class="pagination-prev" href="<?= $context->e((string)$pager['prev_url']) ?>">上一页</a><?php else:?><span class="pagination-prev is-disabled">上一页</span><?php endif;?><?php foreach(($pager['pages']??[]) as $entry):if(!is_array($entry))continue;?><?php if(!empty($entry['current'])):?><span class="pagination-page is-current" aria-current="page"><?= (int)($entry['page']??1) ?></span><?php else:?><a class="pagination-page" href="<?= $context->e((string)($entry['url']??'#')) ?>"><?= (int)($entry['page']??1) ?></a><?php endif;?><?php endforeach;?><?php if(!empty($pager['has_next'])&&!empty($pager['next_url'])):?><a class="pagination-next" href="<?= $context->e((string)$pager['next_url']) ?>">下一页</a><?php else:?><span class="pagination-next is-disabled">下一页</span><?php endif;?><span class="dj-pagination-summary">共 <?= (int)($pager['total_items']??$totalItems) ?> 篇 · 第 <?= (int)($pager['current']??$currentPage) ?> / <?= (int)($pager['total']??$totalPages) ?> 页</span></nav><?php endif;?></main><?php require dirname(__DIR__).'/partials/footer.php';?><script defer src="<?= $context->e($context->asset('js/daojia.js')) ?>"></script></body></html>